-- Migration 0031 (docs/plans/self-serve-photographer.md, S5). Generated by drizzle-kit, then HAND-EDITED where marked. drizzle's migrator runs the
-- whole file in ONE transaction, so SET LOCAL and the advisory lock last exactly this migration and a failure rolls everything back.

-- Hand edit: fail fast instead of queueing behind a long transaction while holding ACCESS EXCLUSIVE locks.
SET LOCAL lock_timeout = '5s';--> statement-breakpoint

-- Hand edit: the role lock every role write takes (src/accounts/role-store.ts lockAccountRoles), so this backfill is ordered against a
-- live old-binary role write during the deploy.
SELECT pg_advisory_xact_lock(hashtextextended('account-roles', 0));--> statement-breakpoint

ALTER TABLE "admin_audit" DROP CONSTRAINT "admin_audit_action_check";--> statement-breakpoint
ALTER TABLE "admin_audit" ADD CONSTRAINT "admin_audit_action_check" CHECK ("admin_audit"."action" IN ('content_import', 'content_publish', 'content_edit', 'content_retire', 'content_restore', 'role_request', 'role_approve', 'role_reject', 'role_grant', 'role_revoke', 'role_block', 'role_unblock', 'role_email_edit', 'media_upload', 'media_version', 'media_edit', 'media_publish', 'media_withdraw', 'content_media_link', 'media_rights', 'media_import', 'store_product_create', 'store_product_edit', 'store_product_retire', 'store_product_restore', 'editorial_create', 'editorial_save', 'content_prepare', 'release_create', 'release_activate', 'release_restore', 'media_review', 'role_self_activate'));--> statement-breakpoint

-- Hand edit: every photographer request still pending is activated (user ruling 2026-11-26: no approval to submit photos), one audit row
-- each, one timestamp for the whole migration at the app clock's precision (milliseconds). `requested_at` keeps its original value.
-- Pending rows without a request email (account deleted, or requested before 0017 added the column) stay pending: the account's next
-- POST /v1/me/roles/photographer activates them.
WITH stamp AS (SELECT date_trunc('milliseconds', now()) AS t),
activated AS (
  UPDATE "account_roles"
  SET "state" = 'active', "revision" = "revision" + 1, "decided_at" = (SELECT t FROM stamp), "decided_by" = 'system:self-serve-0031', "updated_at" = (SELECT t FROM stamp)
  WHERE "role" = 'photographer' AND "state" = 'pending' AND "request_email" IS NOT NULL
  RETURNING "principal", "revision"
)
INSERT INTO "admin_audit" ("actor", "action", "target", "detail", "created_at")
SELECT 'system:self-serve-0031', 'role_self_activate', a."principal",
  jsonb_build_object('role', 'photographer', 'from', jsonb_build_object('state', 'pending', 'revision', a."revision" - 1), 'to', jsonb_build_object('state', 'active', 'revision', a."revision"), 'note', NULL::text),
  (SELECT t FROM stamp)
FROM activated a;
